function innerWalk() {
  for (let i = 0; i < 9; i++) {
    let z = -19.5 - i * 0.5,
      x = -0.065 * i * i;
    for (let k of [-1, 1]) {
      place(
        paverGeo,
        V(x + k * 0.51, Math.abs(z + 18.8) < 1.64 ? 0.52 : 0.36, z),
        V(0.95, 0.5, 0.65),
        k === 1 ? "#c1beaa" : "#b4b6a0",
        [0, 0.08 * i, 0],
        surface("stone"),
      );
    }
  }
}

// 画卷由分层设色、皴笔、远树和题款生成；屋顶、画框和人物都无需下载素材。
function scrollPainting() {
  return canvasTexture(768, 512, (c, w, h) => {
    let g = c.createLinearGradient(0, 0, 0, h);
    g.addColorStop(0, "#eadabd");
    g.addColorStop(0.53, "#ece4cc");
    g.addColorStop(1, "#b4c7b0");
    c.fillStyle = g;
    c.fillRect(0, 0, w, h);
    c.fillStyle = "#dba17c";
    c.beginPath();
    c.arc(555, 116, 29, 0, TAU);
    c.fill();
    for (let layer = 0; layer < 5; layer++) {
      let base = 270 + layer * 44,
        n = 8 + layer,
        profile = [];
      for (let i = 0; i <= n; i++)
        profile.push(rnd(25, 125) * (layer === 4 ? 0.55 : 1));
      let Y = (x) => {
        let q = clamp((x / w) * n, 0, n - 0.0001),
          i = Math.floor(q),
          f = q - i;
        return (
          base -
          lerp(profile[i], profile[i + 1], f * f * (3 - 2 * f)) -
          6 * Math.sin(x * 0.068 + layer)
        );
      };
      c.fillStyle = ["#c2c5b3", "#a7b9a8", "#90a99a", "#668e80", "#50786a"][
        layer
      ];
      c.beginPath();
      c.moveTo(0, h);
      for (let x = 0; x <= w; x += 2) c.lineTo(x, Y(x));
      c.lineTo(w, h);
      c.fill();
      for (let i = 0; i < 380; i++) {
        let x = rnd(0, w),
          y = Y(x) + rnd(2, 55);
        c.strokeStyle = "rgba(48,80,71,.12)";
        c.lineWidth = rnd(0.5, 1.6);
        c.beginPath();
        c.moveTo(x, y);
        c.quadraticCurveTo(x - 2, y + 5, x - rnd(1, 8), y + rnd(4, 16));
        c.stroke();
      }
    }
    paintScrollDetail(c, w, h);
    c.fillStyle = "#465950";
    c.textAlign = "center";
    c.font = "34px KaiTi,SimSun,serif";
    [..."山中長日"].forEach((v, i) => c.fillText(v, 682, 65 + i * 39));
    c.fillStyle = "#ad5846";
    c.fillRect(673, 199, 20, 22);
    c.font = "15px SimSun,serif";
    c.fillStyle = "#ead9b8";
    c.fillText("山", 683, 215);
    for (let i = 0; i < 10000; i++) {
      c.fillStyle =
        rnd() > 0.5 ? "rgba(100,78,53,.045)" : "rgba(255,255,238,.09)";
      c.fillRect(rnd(0, w), rnd(0, h), rnd(0.4, 1.8), 1);
    }
  });
}
function paintingStand(x, z, s, painting) {
  const y = 0.26,
    w = 3.3 * s,
    h = 1.88 * s;
  collidingWall(x, z, w + 0.32, 0.28, 0.05, y + h * 1.18);
  for (let side of [-1, 1]) {
    box(x + side * (w / 2 + 0.13), y + h * 0.55, z, 0.14, h * 1.35, 0.16, wood);
    box(x + side * (w / 2 + 0.13), 0.1, z, 0.6, 0.2, 0.58, "#8a9686");
  }
  box(x, y + h * 0.64, z, w + 0.2, h + 0.21, 0.14, gold);
  let m = single(
    new T.PlaneGeometry(w, h),
    new T.MeshStandardMaterial({ map: painting, roughness: 1 }),
  );
  m.position.set(x, y + h * 0.64, z + 0.078);
  for (let side of [-1, 1])
    beam(
      V(x - w * 0.56, y + h * 0.64 + side * h * 0.51, z + 0.09),
      V(x + w * 0.56, y + h * 0.64 + side * h * 0.51, z + 0.09),
      0.068 * s,
      dark,
    );
}
function tree(x, z, h, palette) {
  collidingWall(x, z, h * 0.09, h * 0.09, -0.05, h * 0.57);
  let base = V(x, -0.05, z),
    tops = [];
  function branch(a, az, len, rad, depth) {
    let lift = depth === 0 ? 0.83 : rnd(0.35, 0.76);
    let b = a
      .clone()
      .add(
        V(
          Math.cos(az) * len * (1 - lift + 0.15),
          len * lift,
          Math.sin(az) * len * (1 - lift + 0.15),
        ),
      );
    let middle = a.clone().lerp(b, 0.55);
    middle.x += Math.cos(az + 0.9) * len * 0.09;
    barkBranch(a, middle, rad, "#786f5b");
    barkBranch(middle, b, rad * 0.76, "#86765e");
    if (depth < 3) {
      for (let i = 0; i < (depth === 0 ? 4 : 3); i++)
        branch(
          b,
          az + (i * TAU) / (depth === 0 ? 4 : 3) + rnd(-0.5, 0.5),
          len * rnd(0.6, 0.84),
          rad * 0.57,
          depth + 1,
        );
    } else tops.push(b);
  }
  branch(base, rnd(0, TAU), h * 0.56, h * 0.045, 0);
  for (let p of tops) {
    let factor = h * 0.18;
    for (let i = 0; i < 18; i++) {
      let a = rnd(0, TAU),
        d = factor * Math.sqrt(rnd()),
        level = rnd(-0.15, 0.23) * factor;
      let pos = p
        .clone()
        .add(V(d * Math.cos(a), level + 0.32 * (factor - d), d * Math.sin(a)));
      let s = rnd(0.67, 1.36) * factor;
      place(
        cardGeo,
        pos,
        V(s, s * 0.84, 1),
        pick(palette),
        [rnd(-0.95, 0.65), rnd(0, TAU), rnd(-0.43, 0.43)],
        foliageCard("leaves"),
      );
    }
  }
}
const willow = ["#79966c", "#8da26b", "#648d70", "#9eae73", "#adc285"],
  amber = ["#bd8c50", "#d4a459", "#eac36d", "#b89a58", "#cfab65"],
  maple = ["#b55f47", "#c97650", "#a65a43", "#cd8958", "#b8724e"];
function flora() {
  let gp = [],
    gi = [],
    gc = [];
  let pos = 0;
  function tri(a, b, c, col) {
    gp.push(...a, ...b, ...c);
    gi.push(pos++, pos++, pos++);
    let color = new T.Color(col);
    for (let i = 0; i < 3; i++) gc.push(color.r, color.g, color.b);
  }
  for (let I of islands) {
    let count = Math.floor(I.rx * I.rz * 6);
    for (let j = 0; j < count; j++) {
      let a = rnd(0, TAU),
        r = Math.sqrt(rnd()) * 0.95;
      let p = islandPoint(I, a, r);
      let pathX = Math.sin((p.z - 4) * 0.27) * 0.86;
      if (Math.abs(p.x - pathX) < 2.4 && I.x === 0) continue;
      if (I.z < 0 && Math.abs(p.z + 18.8) < 2.4) continue;
      let y = I.y + 0.02;
      for (let i = 0; i < 5; i++) {
        let ang = rnd(0, TAU),
          h = rnd(0.13, 0.36),
          dx = Math.cos(ang),
          dz = Math.sin(ang),
          xx = p.x + rnd(-0.16, 0.16),
          zz = p.z + rnd(-0.16, 0.16);
        tri(
          [xx - dz * 0.031, y, zz + dx * 0.031],
          [xx + dz * 0.031, y, zz - dx * 0.031],
          [xx + dx * h * 0.62, y + h, zz + dz * h * 0.62],
          pick(["#619c72", "#81a86b", "#91ba75", "#a4b975", "#5e976d"]),
        );
      }
      if (rnd() < 0.25) {
        let h = rnd(0.2, 0.43);
        for (let k = 0; k < 4; k++) {
          let a = k * PI * 0.5;
          place(
            leafGeo,
            V(p.x + Math.cos(a) * 0.046, y + h, p.z + Math.sin(a) * 0.046),
            V(0.062, 0.025, 0.041),
            pick(["#fff5d4", "#ffefbc", "#fff7e5"]),
            [0, -a, 0],
          );
        }
        oval(V(p.x, y + h + 0.014, p.z), V(0.028, 0.025, 0.028), "#cda350");
      }
      if (r > 0.59 && rnd() < 0.16) {
        for (let k = 0; k < 3; k++) {
          let a = rnd(0, TAU),
            h = rnd(0.64, 1.15),
            dx = Math.cos(a),
            dz = Math.sin(a),
            b = V(p.x + dx * 0.19, y + h, p.z + dz * 0.19);
          beam(V(p.x, y, p.z), b, 0.017, "#a9aa71");
          for (let s = 0; s < 2; s++)
            place(
              cardGeo,
              b.clone().add(V(dx * 0.08, 0.13, dz * 0.08)),
              V(0.21 + 0.13 * Math.abs(dx), 0.34 + 0.17 * Math.abs(dz), 1),
              k % 2 ? "#ccb78a" : "#d2c5a3",
              [dz * 0.34, a + s * PI * 0.5, -dx * 0.34],
              foliageCard("plume"),
            );
        }
      }
    }
  }
  single(
    poly(gp, gi, gc),
    new T.MeshLambertMaterial({ vertexColors: true, side: T.DoubleSide }),
  );
}
const paverGeo = (() => {
  const s = new T.Shape();
  const pts = [
    [-0.47, -0.31],
    [-0.4, -0.48],
    [0.32, -0.5],
    [0.5, -0.32],
    [0.47, 0.3],
    [0.35, 0.47],
    [-0.37, 0.49],
    [-0.5, 0.31],
  ];
  pts.forEach(([x, y], i) => (i ? s.lineTo(x, y) : s.moveTo(x, y)));
  s.closePath();
  let g = new T.ExtrudeGeometry(s, {
    depth: 0.1,
    bevelEnabled: true,
    bevelSegments: 1,
    bevelSize: 0.024,
    bevelThickness: 0.012,
  });
  g.rotateX(-PI / 2);
  return g;
})();
function pathTiles() {
  for (let [from, to, height] of [
    [-0.1, 24, 0.04],
    [-26, -12, 0.32],
  ])
    for (let z = from; z < to; z += 0.96) {
      let center = Math.sin((z - 4) * 0.27) * 0.86;
      for (let i = -1; i <= 1; i++) {
        let x = center + i * 1.18 + rnd(-0.058, 0.058);
        let zz = z + rnd(-0.037, 0.037);
        if (islands.some((I) => islandRatio(I, x, zz) < 0.97))
          place(
            pathSlab(x, zz),
            V(x, height, zz),
            V(
              rnd(1.08, 1.21),
              0.53 + 0.23 * Math.sin(x * 9 + zz),
              rnd(0.932, 0.998),
            ),
            pick(["#c3bda4", "#b7b6a1", "#c9c5ab", "#a7ad98", "#c4bba0"]),
            [0, rnd(-0.073, 0.073), 0],
            surface("stone"),
          );
      }
    }
}
function garden() {
  // 远景山脊已由程序大气全景绘制。
  islands.forEach(makeIsland);
  pathBedding();
  pathTiles();
  let trees = [
    [-5.6, 12.4, 2.65, willow],
    [4.1, 14, 3.4, amber],
    [-3.9, 11.7, 2.65, amber],
    [4.5, -18.9, 4.8, willow],
  ];
  trees.forEach((a) => tree(...a));
  flora();
  let art = scrollPainting();
  atPlace(6.15, 0, 4, -0.52, () => paintingStand(0, 0, 0.93, art));
  paintingStand(-4.8, -23.7, 1.08, art);
  innerWalk();
  for (let [x, z] of [
    [-3.2, 6.1],
    [3.4, -13.4],
    [-3.1, -14.9],
    [3.3, 12.7],
    [-4.7, 3.6],
  ]) {
    collidingWall(x, z, 0.64, 0.64, 0, 1.46);
    box(x, 0.1, z, 0.72, 0.21, 0.72, "#a9ac9a", null, surface("stone"));
    place(tubeGeo, V(x, 0.4, z), V(0.19, 0.56, 0.19), "#879882");
    box(x, 0.74, z, 0.59, 0.17, 0.59, dark);
    box(x, 0.96, z, 0.35, 0.35, 0.35, "#ffe0a1", null, glow);
    for (let a of [-1, 1])
      for (let b of [-1, 1])
        box(x + a * 0.19, 0.96, z + b * 0.19, 0.045, 0.38, 0.045, dark);
    gardenLampCap(x, z);
  }
  for (let j = 0; j < 20; j++) {
    let x = rnd(-28, 30),
      z = rnd(-14, 18);
    if (islands.some((I) => islandRatio(I, x, z) < 1.03)) continue;
    for (let k = 0; k < rnd(3, 7); k++) {
      let rr = rnd(0.12, 0.28);
      place(
        diskGeo,
        V(x + rnd(-0.9, 0.9), -0.8, z + rnd(-0.9, 0.9)),
        V(rr, 0.025, rr * 0.84),
        pick(["#7caa85", "#95b593", "#85a479"]),
      );
    }
  }
}
function localMesh(parent, g, c, p, s, r, mat) {
  let m = new T.Mesh(
    g,
    mat || new T.MeshStandardMaterial({ color: c, roughness: 0.84 }),
  );
  m.position.copy(p);
  m.scale.copy(s);
  if (r) m.rotation.set(...r);
  m.castShadow = true;
  m.receiveShadow = true;
  parent.add(m);
  return m;
}

// 桌面键鼠沿用参考试玩。持印时，左键长按并松开投掷，拖动超过阈值则只转动镜头。
let panorama = false,
  showTrajectory = false,
  hudVisible = true,
  sound = true,
  synth,
  trail;
function chime(notes = [523, 659], volume = 0.035) {
  if (!sound) return;
  try {
    synth ??= new (window.AudioContext || window.webkitAudioContext)();
    if (synth.state === "suspended") synth.resume().catch(() => {});
    notes.forEach((f, i) => {
      let o = synth.createOscillator(),
        g = synth.createGain(),
        t = synth.currentTime + i * 0.1;
      o.type = "sine";
      o.frequency.value = f;
      g.gain.setValueAtTime(0.0001, t);
      g.gain.exponentialRampToValueAtTime(volume, t + 0.017);
      g.gain.exponentialRampToValueAtTime(0.0001, t + 0.65);
      o.connect(g);
      g.connect(synth.destination);
      o.start(t);
      o.stop(t + 0.7);
    });
  } catch {}
}
function optionsPanel() {
  openPanel();
  $("panelTitle").textContent = "光线与画质";
  $("panelBody").innerHTML =
    "<p>画质调整分辨率与水面倒影。精细档增加近景接触阴影。晨光调节会改变整座书院的受光。</p>";
  $("buttons").replaceChildren();
  let b = document.createElement("button");
  b.textContent = "画质 · " + qualityNames[quality];
  b.onclick = () => {
    qualitySet((quality + 1) % 3);
    b.textContent = "画质 · " + qualityNames[quality];
  };
  $("buttons").append(b);
  let l = document.createElement("button");
  l.textContent = "切换晨光";
  l.onclick = () => {
    shadowLight.intensity = shadowLight.intensity > 2.5 ? 2.05 : 3.3;
    if (inInk) renderer.render(scene, inkCamera);
    else renderLandscape();
    l.textContent = shadowLight.intensity > 2.5 ? "晨光 · 明亮" : "晨光 · 柔和";
  };
  $("buttons").append(l);
  menuButton("返回游戏", resume, true);
}
function rewind() {
  if (inInk) {
    leaveInk(false);
    return;
  }
  let a = actors[active];
  clearStride(a);
  a.root.position.set(0, stage >= 2 ? 0.39 : 0.11, stage >= 2 ? -14 : 9.2);
  a.v = 0;
  a.ground = true;
  a.roll = 0;
  cameraSet = false;
  notify("已回到本卷岸边");
}
function trajectory() {
  if (!trail) {
    let a = new Float32Array(25 * 3),
      g = new T.BufferGeometry();
    g.setAttribute("position", new T.BufferAttribute(a, 3));
    trail = new T.Line(
      g,
      new T.LineDashedMaterial({
        color: "#fff3be",
        dashSize: 0.14,
        gapSize: 0.12,
        transparent: true,
        opacity: 0.83,
      }),
    );
    trail.frustumCulled = false;
    scene.add(trail);
  }
  trail.visible = held && holder === active && (showTrajectory || charging > 0);
  if (!trail.visible) return;
  let a = actors[active],
    p = a.root.position,
    start = p.clone().add(V(0, 1.1, 0)),
    d = 3.2 + Math.min(charging, 1.4) * 3.15,
    end = start
      .clone()
      .add(V(-Math.sin(a.facing) * d, 0, -Math.cos(a.facing) * d));
  end.y = support(end.x, end.z) + 0.03;
  if (gap(end, desk) < 1.45) end.set(desk.x, 0.84, desk.z);
  let buf = trail.geometry.attributes.position;
  for (let i = 0; i < 25; i++) {
    let t = i / 24,
      v = start.clone().lerp(end, t);
    buf.setXYZ(i, v.x, v.y + 5 * t * (1 - t), v.z);
  }
  buf.needsUpdate = true;
  trail.computeLineDistances();
}
function contact(a) {
  let p = a.root.position,
    h = Math.max(support(p.x, p.z, p.y), onObstacle(p.x, p.z, p.y)),
    d = Math.max(0, p.y - h);
  a.shadow.visible = h > -1;
  // 软投影沿晨光的反方向延伸，离地时减淡。
  a.shadow.position.set(p.x - morningSun.x * .32, h + .026, p.z - morningSun.z * .32);
  a.shadow.rotation.z = Math.atan2(morningSun.z, -morningSun.x);
  a.shadow.scale.set(1.42 + d * .18, .79 + d * .1, 1);
  a.shadow.material.opacity = .87 / (1 + d);

  for (const { bone, patch } of a.footContacts) {
    patch.visible = a.ground && a.shadow.visible && a.roll <= 0;
    if (patch.visible) {
      bone.getWorldPosition(patch.position);
      const foot = patch.position;
      const floor = Math.max(support(foot.x, foot.z, p.y), onObstacle(foot.x, foot.z, p.y));
      patch.visible = floor > -1;
      const gap = Math.max(0, foot.y - floor - .028);
      patch.material.opacity = Math.exp(-gap * 5);
      patch.scale.set(.39 + .24 * gap, .28 + .18 * gap, 1);
      patch.position.y = floor + .032;
    }
  }
}

