  for(const z of centers){
    const cut=new T.Path();
    windowPoints.forEach(([a,b],i)=>cut[i?'lineTo':'moveTo'](-z+a,2.28+b));
    cut.closePath();outline.holes.push(cut);
  }
  const wall=single(new T.ExtrudeGeometry(outline,{depth:.16,bevelEnabled:false}),new T.MeshStandardMaterial({color:"#d6d0b9",map:surface("paper").map,roughness:.92}));
  wall.rotation.y=PI/2;wall.position.x=side*4.26-.08;
