    beam(
      V(x - .39*scale, y + s * .875*scale, z),
      V(x + .39*scale, y + s * .875*scale, z),
      0.026,
      "#705941",
    );
  beam(
    V(x - .31*scale, y + .895*scale, z - 0.01),
    V(x, y + 1.14*scale, z - 0.025),
    0.006,
    "#9e815b",
  );
  beam(
    V(x, y + 1.14*scale, z - 0.025),
    V(x + .31*scale, y + .895*scale, z - 0.01),
    0.006,
    "#9e815b",
  );
