// 石板之间露出连续的夯砂垫层。按小间距裁去岛岸外的条带。
function pathBedding() {
  const p = [],
    uv = [],
    ix = [];
  for (let [from, to, h] of [
    [-0.23, 24.2, 0.058],
    [-26.2, -11.9, 0.341],
  ]) {
    for (let row = 0; row < Math.ceil((to - from) * 4); row++) {
      let z0 = from + row * 0.25,
        z1 = z0 + 0.25;
      const center = (z) => Math.sin((z - 4) * 0.27) * 0.86;
      for (let col = -6; col < 6; col++) {
        const xa = col * 0.282,
          xb = xa + 0.282;
        if (
          !islands.some(
            (I) => islandRatio(I, center(z0) + (xa + xb) / 2, z0) < 0.954,
          )
        )
          continue;
        const k = p.length / 3;
        for (const [x, z] of [
          [xa, z0],
          [xa, z1],
          [xb, z1],
          [xb, z0],
        ]) {
          const xx = x + center(z);
          p.push(xx, h + 0.003 * Math.sin(xx * 3 + z * 4), z);
          uv.push(xx * 0.88, z * 0.88);
        }
        ix.push(k, k + 1, k + 2, k, k + 2, k + 3);
      }
    }
  }
  const mat = new T.MeshStandardMaterial({
    map: photoMaps.shale,
    normalMap: photoMaps["earth-normal"],
    color: "#bdb299",
    roughness: 0.94,
  });
  const bed = single(poly(p, ix, null, uv), mat);
  bed.castShadow = false;
}
// 东岭的岩肩、冲沟和坡积物属于同一片连续地形，游径周围保留既有标高。
function erodeEastRidge() {
  const original = field.slice(),
    n = field.length,
    allowed = new Float32Array(n);
  const ridges = [
    [631, 133, 19, 8, 0.62, 4.1],
    [623, 143, 12, 8, -0.87, 3.1],
    [605, 151, 20, 10, -0.73, 3.5],
    [590, 162, 14, 11, 0.35, 4.2],
    [587, 145, 19, 7, -0.56, 2.6],
    [576, 147, 10, 9, 0.39, 2.3],
    [615, 165, 11, 5, -0.74, 2.2],
    [648, 121, 16, 9, 0.93, 2.8],
  ];
  const lowI = Math.floor((548-originU)/cell),
    highI = Math.ceil((728-originU)/cell),
    lowJ = 43,
    highJ = 141;
  for (let j = lowJ; j < highJ; j++)
    for (let i = lowI; i < highI; i++) {
      const k = j * nU + i,
        u = originU + i * cell,
        v = originV + j * cell,
        h = field[k];
      if (h < 0.1 || (u > 693 && padMargin(u, v, housePads[0]) < 0.6)) continue;
      const safe =
        T.MathUtils.smoothstep(nearbyRoute(u, v)[0], 4.5, 12) *
        T.MathUtils.smoothstep(h, 0.15, 3);
      allowed[k] = safe;
      if (!safe) continue;
      let uplift = 0;
      for (const [cx, cz, w, d, az, rise] of ridges) {
        const x = u - cx,
          z = v - cz,
          along = (x * Math.cos(az) + z * Math.sin(az)) / w,
          across = (-x * Math.sin(az) + z * Math.cos(az)) / d;
        const cut = across + 0.14 * Math.sin(along * 3.3 + az);
        const taper = Math.max(0, 1 - along * along);
        const ledge =
          T.MathUtils.smoothstep(cut, -1.1, -0.28) *
            (1 - T.MathUtils.smoothstep(cut, 0.18, 0.55)) +
          0.36 *
            T.MathUtils.smoothstep(cut, 0.11, 0.52) *
            (1 - T.MathUtils.smoothstep(cut, 0.53, 1.12));
        uplift = Math.max(uplift, rise * taper * ledge);
      }
      field[k] += safe * uplift * 0.47;
    }
  // 从山腰放出径流。每一步从邻格中选择更低处，坡度减小时沉积携带的岩屑。
  const flowSeed = seed;
  seed = 28544;
  for (let drop = 0; drop < 8500; drop++) {
    let i = Math.floor(rnd(lowI + 2, highI - 2)),
      j = Math.floor(rnd(lowJ + 2, highJ - 2)),
      load = 0;
    for (let step = 0; step < 26; step++) {
      let k = j * nU + i;
      if (!allowed[k]) break;
      let next = k,
        grade = 0.02;
      for (let dy = -1; dy <= 1; dy++)
        for (let dx = -1; dx <= 1; dx++) {
          if (!dx && !dy) continue;
          const q = k + dx + dy * nU,
            g = (field[k] - field[q]) / Math.hypot(dx, dy);
          if (g > grade) {
            grade = g;
            next = q;
          }
        }
      if (next === k) {
        field[k] += 0.2 * load * allowed[k];
        break;
      }
      const capacity = Math.min(0.24, grade * 0.12),
        amount = (capacity - load) * allowed[k] * 0.34;
      field[k] -= amount;
      load += amount;
      field[k] = Math.max(original[k] - 1.1, field[k]);
      j = Math.floor(next / nU);
      i = next - j * nU;
    }
  }
  seed = flowSeed;
}
