function support(x, z, y) {
  if (inInk) return inkFloor(x, z);
  const upstairs = stairHeight(x, z, y);
  if (upstairs !== null) return upstairs;
  const outside = Math.max(courtFloor(x,z), worldGround(x, z));
  if (outside > -0.49 && z < -21) return outside;
  if(Math.abs(x)<2.67 && z>=-15.9 && z<=-11.92) return -.225+.098*clamp(Math.round((-12.15-z)/.44),0,8);
  if (Math.abs(z + 18.8) < 1.64 && Math.abs(x) < 20.05) return 0.52;
  for (let I of islands) {
    if (islandRatio(I, x, z) < 0.97) {
      if (
        z >= -21 &&
        outside > I.y + 0.11 &&
        nearbyRoute(...paperPoint(x, z))[0] < 2.5
      )
        return outside;
      return I.y + 0.11;
    }
  }
  if (stage >= 2 && bridgeRise > 0.88) {
    for (let b of bridge)
      if (
        Math.abs(x - b.position.x) < 1.37 &&
        Math.abs(z - b.userData.z) < 0.65
      )
        return b.userData.top;
  }
  return worldGround(x, z);
}
